SELECT LOWER(COLUMN_NAME) AS column_name,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='crew_calendar' ORDER BY ORDINAL_POSITION;
SELECT INDEX_NAME,SEQ_IN_INDEX,LOWER(COLUMN_NAME) AS column_name FROM information_schema.STATISTICS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='crew_calendar' AND INDEX_NAME='PRIMARY' ORDER BY SEQ_IN_INDEX;

SELECT k.COLUMN_NAME,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME,UPDATE_RULE
FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r USING(CONSTRAINT_SCHEMA,CONSTRAINT_NAME,TABLE_NAME)
WHERE k.TABLE_SCHEMA=DATABASE() AND k.TABLE_NAME='supply_pick';

SELECT LOWER(COLUMN_NAME) AS column_name,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT FROM information_schema.COLUMNS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='supply_ticket' ORDER BY ORDINAL_POSITION;
SELECT INDEX_NAME,SEQ_IN_INDEX,LOWER(COLUMN_NAME) AS column_name FROM information_schema.STATISTICS
WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='supply_ticket' AND INDEX_NAME='PRIMARY' ORDER BY SEQ_IN_INDEX;
